export const defaultState = {version:1,grade:10,name:'Nhà thám hiểm',completed:[],saved:[],notes:[],trials:[],viewed:[]};
export function cleanState(raw){
 const v=raw&&typeof raw==='object'?raw:{}; const ids=new Set(lessons.map(x=>x.id));
 return {...defaultState,grade:[10,11,12].includes(v.grade)?v.grade:10,name:typeof v.name==='string'?v.name.slice(0,40):defaultState.name,completed:[...new Set(Array.isArray(v.completed)?v.completed:[])].filter(x=>ids.has(x)),saved:[...new Set(Array.isArray(v.saved)?v.saved:[])].filter(x=>ids.has(x)),viewed:[...new Set(Array.isArray(v.viewed)?v.viewed:[])].filter(x=>['cell','dna'].includes(x)),notes:(Array.isArray(v.notes)?v.notes:[]).filter(x=>x&&typeof x.id==='string'&&typeof x.title==='string'&&typeof x.body==='string').slice(0,100).map(x=>({id:x.id,title:x.title.slice(0,100),body:x.body.slice(0,6000),date:typeof x.date==='string'?x.date:''})),trials:(Array.isArray(v.trials)?v.trials:[]).filter(x=>x&&[x.light,x.co2,x.rate].every(n=>typeof n==='number'&&Number.isFinite(n)&&n>=0&&n<=100)).slice(-20)};
}
export function experimentRate(light,co2){return Math.round(Math.min(Math.max(0,light)/70,1)*Math.min(Math.max(0,co2)/65,1)*100)}
export function xpFor(s){return s.completed.length*30+s.viewed.length*10+(s.trials.length?20:0)}
export function escapeHTML(v){return String(v).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]))}
export function normalize(v){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase()}
